## Skill Priority

When multiple skills could apply, use this order:

1. **Process skills first** (brainstorming, debugging) - these determine HOW to approach the task
2. **Implementation skills second** (frontend-design, mcp-builder) - these guide execution

"Let's build X" â†’ brainstorming first, then implementation skills.
"Fix this bug" â†’ debugging first, then domain-specific skills.

## Skill Types

**Rigid** (TDD, debugging): Follow exactly. Don't adapt away discipline.

**Flexible** (patterns): Adapt principles to context.

The skill itself tells you which.

## User Instructions

Instructions say WHAT, not HOW. "Add X" or "Fix Y" doesn't mean skip workflows.

"""Tool registry for managing available tools."""
from __future__ import annotations

from sage.tools.base import Tool


class ToolRegistry:
    """Registry for managing tools available to agents."""

    def __init__(self) -> None:
        self._tools: dict[str, Tool] = {}
        self._usage: dict[str, dict] = {}  # name -> {usage_count, success_count, source}

    def register(self, tool: Tool) -> None:
        """Register a tool."""
        self._tools[tool.spec.name] = tool

    def get(self, name: str) -> Tool | None:
        """Get a tool by name."""
        return self._tools.get(name)

    def list_tools(self) -> list[str]:
        """List all registered tool names."""
        return list(self._tools.keys())

    def search(self, query: str) -> list[Tool]:
        """Search tools by name or description."""
        query_lower = query.lower()
        return [
            tool
            for tool in self._tools.values()
            if query_lower in tool.spec.name.lower()
            or query_lower in tool.spec.description.lower()
        ]

    def get_tool_defs(self, names: list[str] | None = None) -> list:
        """Get tool definitions in OpenAI function-calling format."""
        specs = (
            [t.spec for t in self._tools.values()]
            if names is None
            else [self._tools[n].spec for n in names if n in self._tools]
        )
        return [
            {
                "type": "function",
                "function": {
                    "name": s.name,
                    "description": s.description,
                    "parameters": s.parameters,
                },
            }
            for s in specs
        ]

    # â”€â”€ Usage tracking (ToolForge axis) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    def record_usage(self, name: str, success: bool = True) -> None:
        """Record a tool invocation for usage tracking."""
        if name not in self._usage:
            self._usage[name] = {"usage_count": 0, "success_count": 0, "source": "builtin"}
        self._usage[name]["usage_count"] += 1
        if success:
            self._usage[name]["success_count"] += 1

    def get_usage(self, name: str) -> dict:
        """Get usage stats for a tool. Returns default dict if unknown."""
        return self._usage.get(name, {"usage_count": 0, "success_count": 0, "source": "builtin"})

    def mark_source(self, name: str, source: str) -> None:
        """Mark the origin of a tool (builtin, forged, user)."""
        if name not in self._usage:
            self._usage[name] = {"usage_count": 0, "success_count": 0, "source": source}
        else:
            self._usage[name]["source"] = source

"""AgeMem memory tools: 8 learnable actions for STM + LTM + Causal management.

Research basis:
- AgeMem: Unified tool-based memory policy (RETRIEVE/SUMMARY/FILTER + ADD/UPDATE/DELETE)
- NotebookLM Technical: Two-stage provenance-aware retrieval
- MEM1: Rolling internal state via compressor
- AMA-Bench (2602.22769): Causal memory for provenance tracking
"""
from __future__ import annotations

from typing import Any

from sage.tools.base import Tool
from sage.memory.episodic import EpisodicMemory
from sage.memory.working import WorkingMemory


def create_search_memory_tool(episodic: EpisodicMemory) -> Tool:
    """Legacy: create a single search_memory tool. Use create_memory_tools() instead."""

    @Tool.define(
        name="search_memory",
        description=(
            "Search long-term episodic memory for relevant past experiences. "
            "Use when current context is insufficient to answer the task."
        ),
        parameters={
            "type": "object",
            "properties": {
                "query": {"type": "string", "description": "What to search for in memory"},
                "top_k": {"type": "integer", "description": "Max results to return", "default": 5},
            },
            "required": ["query"],
        },
    )
    async def search_memory(query: str, top_k: int = 5) -> str:
        results = await episodic.search(query, top_k=top_k)
        if not results:
            return "No relevant memories found."
        lines = [f"[{r['key']}] {r['content']}" for r in results]
        return "\n".join(lines)

    return search_memory


def create_memory_tools(
    working_memory: WorkingMemory,
    episodic: EpisodicMemory,
    compressor: Any | None = None,
    causal_memory: Any | None = None,
) -> list[Tool]:
    """Create all 8 AgeMem memory tools bound to the memory instances.

    STM (Working Memory): retrieve_context, summarize_context, filter_context
    LTM (Episodic): search_memory, store_memory, update_memory, delete_memory
    Causal: search_causal_chain
    """
    tools: list[Tool] = []

    # --- STM Tools (Working Memory) ---

    @Tool.define(
        name="retrieve_context",
        description="Retrieve the N most recent events from short-term working memory.",
        parameters={
            "type": "object",
            "properties": {
                "n": {"type": "integer", "description": "Number of recent events to retrieve", "default": 10},
            },
            "required": [],
        },
    )
    async def retrieve_context(n: int = 10) -> str:
        events = working_memory.recent_events(n)
        if not events:
            return "Working memory is empty."
        lines = [f"[{e['type']}] {e['content']}" for e in events]
        return "\n".join(lines)

    tools.append(retrieve_context)

    @Tool.define(
        name="summarize_context",
        description="Get the current internal state summary (rolling MEM1 IS) of the agent's memory.",
        parameters={"type": "object", "properties": {"_": {"type": "string", "description": "Unused (no-arg tool). Pass empty string."}}, "required": []},
    )
    async def summarize_context() -> str:
        if compressor and hasattr(compressor, "internal_state") and compressor.internal_state:
            return f"Internal State: {compressor.internal_state}"
        ctx = working_memory.to_context_string()
        return ctx[:1000] if ctx else "No context available."

    tools.append(summarize_context)

    @Tool.define(
        name="filter_context",
        description="Trim working memory to keep only the N most recent events. Use to drop irrelevant early context.",
        parameters={
            "type": "object",
            "properties": {
                "keep_recent": {"type": "integer", "description": "Number of recent events to keep", "default": 5},
            },
            "required": [],
        },
    )
    async def filter_context(keep_recent: int = 5) -> str:
        count_before = working_memory.event_count()
        if count_before <= keep_recent:
            return f"Nothing to filter. Working memory has {count_before} events."
        working_memory.compress(keep_recent, "Filtered by agent request.")
        return f"Filtered working memory from {count_before} to ~{keep_recent} events."

    tools.append(filter_context)

    # --- LTM Tools (Episodic Memory) ---

    @Tool.define(
        name="search_memory",
        description="Search long-term episodic memory for relevant past experiences.",
        parameters={
            "type": "object",
            "properties": {
                "query": {"type": "string", "description": "What to search for in memory"},
                "top_k": {"type": "integer", "description": "Max results to return", "default": 5},
            },
            "required": ["query"],
        },
    )
    async def search_memory(query: str, top_k: int = 5) -> str:
        results = await episodic.search(query, top_k=top_k)
        if not results:
            return "No relevant memories found."
        lines = [f"[{r['key']}] {r['content']}" for r in results]
        return "\n".join(lines)

    tools.append(search_memory)

    @Tool.define(
        name="store_memory",
        description="Store a new entry in long-term episodic memory for future retrieval.",
        parameters={
            "type": "object",
            "properties": {
                "key": {"type": "string", "description": "Unique identifier for this memory"},
                "content": {"type": "string", "description": "The content to store"},
            },
            "required": ["key", "content"],
        },
    )
    async def store_memory(key: str, content: str) -> str:
        await episodic.store(key, content)
        return f"Stored memory '{key}' successfully."

    tools.append(store_memory)

    @Tool.define(
        name="update_memory",
        description="Update an existing long-term memory entry by key.",
        parameters={
            "type": "object",
            "properties": {
                "key": {"type": "string", "description": "Key of the memory to update"},
                "content": {"type": "string", "description": "New content to replace the old"},
            },
            "required": ["key", "content"],
        },
    )
    async def update_memory(key: str, content: str) -> str:
        updated = await episodic.update(key, content=content)
        if updated:
            return f"Updated memory '{key}' successfully."
        return f"Memory '{key}' not found. Use store_memory to create it."

    tools.append(update_memory)

    @Tool.define(
        name="delete_memory",
        description="Delete an obsolete or incorrect long-term memory entry.",
        parameters={
            "type": "object",
            "properties": {
                "key": {"type": "string", "description": "Key of the memory to delete"},
            },
            "required": ["key"],
        },
    )
    async def delete_memory(key: str) -> str:
        deleted = await episodic.delete(key)
        if deleted:
            return f"Deleted memory '{key}' successfully."
        return f"Memory '{key}' not found."

    tools.append(delete_memory)

    # --- Causal Memory Tools ---

    if causal_memory is not None:

        @Tool.define(
            name="search_causal_chain",
            description=(
                "Trace causal chains in memory. Given an entity, find what it caused "
                "(forward chain) or what caused it (ancestors). Use for provenance "
                "tracking and understanding cause-effect relationships."
            ),
            parameters={
                "type": "object",
                "properties": {
                    "entity": {
                        "type": "string",
                        "description": "The entity to trace causal chains for",
                    },
                    "direction": {
                        "type": "string",
                        "enum": ["forward", "backward"],
                        "description": "forward = what this entity caused; backward = what caused this entity",
                        "default": "forward",
                    },
                },
                "required": ["entity"],
            },
        )
        async def search_causal_chain(entity: str, direction: str = "forward") -> str:
            if direction == "backward":
                chain = causal_memory.get_causal_ancestors(entity)
                label = "Ancestors (what caused this)"
            else:
                chain = causal_memory.get_causal_chain(entity)
                label = "Causal chain (what this caused)"
            if not chain:
                return f"No causal chain found for '{entity}'."
            return f"{label}: {' -> '.join(chain)}"

        tools.append(search_causal_chain)

    return tools

"""ExoCortex agent tools: search_exocortex."""
from __future__ import annotations

import asyncio
from typing import Any

from sage.tools.base import Tool


def create_exocortex_tools(exocortex: Any) -> list[Tool]:
    """Create ExoCortex tools bound to the given ExoCortex instance."""
    tools: list[Tool] = []

    @Tool.define(
        name="search_exocortex",
        description=(
            "Search the ExoCortex knowledge store for research papers and insights. "
            "Use when you need specific research knowledge about MARL, cognitive architectures, "
            "formal verification, evolutionary computation, or memory systems."
        ),
        parameters={
            "type": "object",
            "properties": {
                "query": {"type": "string", "description": "Research question to search for"},
                "domain": {
                    "type": "string",
                    "description": "Optional domain filter: marl, cognitive_architectures, formal_verification, evolutionary_computation, memory_systems",
                },
            },
            "required": ["query"],
        },
    )
    async def search_exocortex(query: str, domain: str | None = None) -> str:
        if not exocortex or not exocortex.store_name:
            return "ExoCortex not configured. Set SAGE_EXOCORTEX_STORE environment variable."
        result = await asyncio.to_thread(exocortex.query, query, domain)
        if not result:
            return "No relevant results found in ExoCortex."
        return result

    tools.append(search_exocortex)

    @Tool.define(
        name="refresh_knowledge",
        description=(
            "Trigger on-demand knowledge discovery: scan arXiv, Semantic Scholar, "
            "and HuggingFace for new papers, curate them, and ingest into ExoCortex. "
            "Use when you need the latest research on a specific topic."
        ),
        parameters={
            "type": "object",
            "properties": {
                "query": {"type": "string", "description": "Research topic to search for"},
                "domain": {
                    "type": "string",
                    "description": "Optional domain: marl, cognitive_architectures, formal_verification, evolutionary_computation, memory_systems",
                },
            },
            "required": [],
        },
    )
    async def refresh_knowledge(query: str | None = None, domain: str | None = None) -> str:
        try:
            from discover.pipeline import run_pipeline

            domains = [domain] if domain else None
            report = await run_pipeline(
                mode="on-demand" if query else "nightly",
                query=query,
                domains=domains,
                exocortex=exocortex,
            )
            return (
                f"Knowledge refresh complete: "
                f"{report.discovered} discovered, "
                f"{report.curated} curated, "
                f"{report.ingested} ingested."
            )
        except ImportError:
            return "Knowledge pipeline not available. Install sage-discover."
        except Exception as e:
            return f"Knowledge refresh failed: {e}"

    tools.append(refresh_knowledge)
    return tools

"""Meta-tools for dynamic tool synthesis.

Enables agents to write, register, and manage their own tools dynamically.
Uses subprocess-based sandboxed execution with AST validation to prevent
arbitrary code execution in the host process.
"""
from __future__ import annotations

import asyncio
import json
import sys
import os
import logging
import shlex
from typing import Callable

from sage.tools.base import Tool
from sage.tools.registry import ToolRegistry
from sage.tools.sandbox_executor import validate_tool_code, execute_python_in_sandbox
from sage.llm.base import ToolDef

logger = logging.getLogger(__name__)

TOOLS_WORKSPACE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "generated_tools")
os.makedirs(TOOLS_WORKSPACE, exist_ok=True)

_READ_ONLY_COMMANDS: tuple[tuple[str, ...], ...] = (
    ("git", "diff"),
    ("git", "log"),
    ("git", "show"),
    ("git", "status"),
    ("cat",),
    ("date",),
    ("df",),
    ("du",),
    ("echo",),
    ("file",),
    ("find",),
    ("grep",),
    ("head",),
    ("ls",),
    ("printf",),
    ("pwd",),
    ("rg",),
    ("sort",),
    ("stat",),
    ("tail",),
    ("tree",),
    ("uniq",),
    ("wc",),
    ("whoami",),
)

_EXACT_SHELL_OPERATOR_TOKENS = {
    ";", ";;", "&", "&&", "|", "||", ">", ">>", "<", "<<", "<<<",
}
_CONTROL_CHARS = tuple(chr(i) for i in range(32) if chr(i) not in ("\t",))


def _format_allowed_commands() -> str:
    return ", ".join(" ".join(parts) for parts in _READ_ONLY_COMMANDS)


def _reject_control_chars(argv: list[str]) -> str | None:
    for arg in argv:
        if "\x00" in arg or any(ch in arg for ch in _CONTROL_CHARS):
            return "Blocked: Control characters are not allowed in bash tool commands."
    return None


def _reject_shell_operators(argv: list[str]) -> str | None:
    for arg in argv:
        if arg in _EXACT_SHELL_OPERATOR_TOKENS:
            return (
                "Blocked: Shell operators are not supported. "
                "Pass a single command with arguments only."
            )
    return None


def _validate_find_args(args: list[str]) -> str | None:
    blocked = {
        "-delete", "-exec", "-execdir", "-ok", "-okdir",
        "-fprint", "-fprint0", "-fprintf", "-fls",
    }
    for arg in args:
        if arg in blocked:
            return f"Blocked: find argument '{arg}' is not allowed."
    return None


def _validate_rg_args(args: list[str]) -> str | None:
    for arg in args:
        if arg == "--pre" or arg.startswith("--pre="):
            return "Blocked: rg --pre is not allowed in bash tools."
        if arg == "--pre-glob" or arg.startswith("--pre-glob="):
            return "Blocked: rg --pre-glob is not allowed in bash tools."
    return None


def _validate_git_args(args: list[str]) -> str | None:
    for arg in args:
        if arg == "--output" or arg.startswith("--output="):
            return "Blocked: git --output is not allowed in bash tools."
        if arg == "--ext-diff":
            return "Blocked: git --ext-diff is not allowed in bash tools."
        if arg == "--textconv":
            return "Blocked: git --textconv is not allowed in bash tools."
    return None


def _validator_for(prefix: tuple[str, ...]) -> Callable[[list[str]], str | None]:
    if prefix == ("find",):
        return _validate_find_args
    if prefix == ("rg",):
        return _validate_rg_args
    if prefix[0] == "git":
        return _validate_git_args
    return lambda _args: None


def _parse_bash_tool_command(script: str) -> tuple[list[str] | None, str | None]:
    script_stripped = script.strip()
    if not script_stripped:
        return None, "Blocked: Empty script."
    if "\n" in script_stripped or "\r" in script_stripped:
        return None, "Blocked: Multi-line bash tool scripts are not allowed."

    try:
        argv = shlex.split(script_stripped, posix=True)
    except ValueError as exc:
        return None, f"Blocked: Invalid shell quoting: {exc}"

    if not argv:
        return None, "Blocked: Empty script."

    control_error = _reject_control_chars(argv)
    if control_error:
        return None, control_error

    operator_error = _reject_shell_operators(argv)
    if operator_error:
        return None, operator_error

    matched_prefix: tuple[str, ...] | None = None
    for prefix in sorted(_READ_ONLY_COMMANDS, key=len, reverse=True):
        if argv[: len(prefix)] == list(prefix):
            matched_prefix = prefix
            break

    if matched_prefix is None:
        return (
            None,
            "Blocked: Command not in allowlist. "
            f"Permitted commands: {_format_allowed_commands()}",
        )

    validator = _validator_for(matched_prefix)
    arg_error = validator(argv[len(matched_prefix):])
    if arg_error:
        return None, arg_error

    return argv, None


def _build_isolated_exec_wrapper(argv: list[str]) -> str:
    argv_literal = json.dumps(argv)
    return (
        "import json\n"
        "import subprocess\n"
        "import sys\n"
        f"argv = json.loads({argv_literal!r})\n"
        "proc = subprocess.run(argv, capture_output=True, text=True, shell=False)\n"
        "sys.stdout.write(proc.stdout)\n"
        "sys.stderr.write(proc.stderr)\n"
        "raise SystemExit(proc.returncode)\n"
    )

@Tool.define(
    name="create_python_tool",
    description="Dynamically writes and registers a new Python tool. The code is saved persistently to disk and formally validated before registration.",
    parameters={
        "type": "object",
        "properties": {
            "name": {"type": "string", "description": "The name of the new tool"},
            "code": {"type": "string", "description": "The complete Python code for the tool, including imports and @Tool.define"}
        },
        "required": ["name", "code"]
    }
)
async def create_python_tool(name: str, code: str, registry: ToolRegistry = None) -> str:
    if not registry:
        return "Error: Tool registry not available for dynamic registration."

    # Try Rust path first (tree-sitter validation + subprocess)
    try:
        from sage_core import ToolExecutor
        _executor = ToolExecutor()

        # Validate via tree-sitter
        validation = _executor.validate(code)
        if not validation.valid:
            return "Blocked: " + "; ".join(validation.errors)

        # Create sandboxed handler using Rust executor
        saved_code = code
        async def _rust_handler(**kwargs):
            result = _executor.execute_raw(saved_code, json.dumps(kwargs))
            if result.exit_code != 0:
                return f"Error (exit {result.exit_code}): {result.stderr.strip()}"
            stdout = result.stdout.strip()
            try:
                parsed = json.loads(stdout)
                if isinstance(parsed, dict) and "output" in parsed:
                    return str(parsed["output"])
            except (json.JSONDecodeError, TypeError):
                pass
            return stdout

        handler = _rust_handler
        logger.info("Using Rust ToolExecutor for tool '%s'", name)

    except (ImportError, AttributeError):
        # Fallback: Python sandbox_executor
        errors = validate_tool_code(code)
        if errors:
            return "Blocked: " + "; ".join(errors)

        saved_code = code
        async def _python_handler(**kwargs):
            result = await execute_python_in_sandbox(saved_code, kwargs)
            if result.exit_code != 0:
                return f"Error (exit {result.exit_code}): {result.stderr.strip()}"
            stdout = result.stdout.strip()
            try:
                parsed = json.loads(stdout)
                if isinstance(parsed, dict) and "output" in parsed:
                    return str(parsed["output"])
            except (json.JSONDecodeError, TypeError):
                pass
            return stdout

        handler = _python_handler
        logger.info("Using Python sandbox for tool '%s' (Rust ToolExecutor not available)", name)

    # Save code for auditability
    file_path = os.path.join(TOOLS_WORKSPACE, f"{name}.py")
    try:
        with open(file_path, "w", encoding="utf-8") as f:
            f.write(code)
    except OSError as e:
        return f"Error: Could not save tool code: {e}"

    # Register tool
    tool_spec = ToolDef(
        name=name,
        description=f"Dynamically created tool '{name}' (sandboxed).",
        parameters={
            "type": "object",
            "properties": {"_": {"type": "string", "description": "Unused. Pass empty string."}},
        },
    )
    new_tool = Tool(spec=tool_spec, handler=handler)
    registry.register(new_tool)

    logger.info("Registered sandboxed tool '%s' (saved to %s)", name, file_path)
    return f"Success: Tool '{name}' has been created, validated, saved to {file_path}, and registered (sandboxed)."


@Tool.define(
    name="create_bash_tool",
    description="Creates a persistent tool that wraps a specific bash command or script. Executed via secure subprocess.",
    parameters={
        "type": "object",
        "properties": {
            "name": {"type": "string", "description": "Name of the new tool"},
            "description": {"type": "string", "description": "What the tool does"},
            "script": {"type": "string", "description": "The bash script to execute"}
        },
        "required": ["name", "description", "script"]
    }
)
async def create_bash_tool(name: str, description: str, script: str, registry: ToolRegistry = None) -> str:
    # 1. Registry required
    if not registry:
        return "Error: Tool registry not available for dynamic registration."

    # 2. Security gate: parse to argv and validate against an explicit read-only allowlist.
    argv, validation_error = _parse_bash_tool_command(script)
    if validation_error:
        return validation_error
    assert argv is not None

    # 3. Build sandbox-isolated handler closure
    saved_argv = list(argv)

    async def _bash_handler(**kwargs):
        try:
            # Use Rust sandbox executor if available, subprocess fallback with strict limits
            from sage.sandbox.isolated_executor import execute_isolated
            wrapper = _build_isolated_exec_wrapper(saved_argv)
            stdout, stderr, exit_code = execute_isolated(wrapper, timeout=30)
            if exit_code == 0:
                return stdout.strip()
            else:
                return f"Error (exit {exit_code}): {stderr.strip()}"
        except ImportError:
            # Fallback: direct argv execution with no shell.
            try:
                proc = await asyncio.create_subprocess_exec(
                    *saved_argv,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                )
                stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)
                stdout_text = stdout.decode("utf-8", errors="replace").strip()
                stderr_text = stderr.decode("utf-8", errors="replace").strip()
                if proc.returncode == 0:
                    return stdout_text
                return f"Error (exit {proc.returncode}): {stderr_text}"
            except asyncio.TimeoutError:
                if proc.returncode is None:
                    proc.kill()
                    await proc.communicate()
                return "Error: Script execution timed out after 30 seconds."
        except Exception as e:
            return f"Error: {type(e).__name__}: {e}"

    # 4. Register tool
    tool_spec = ToolDef(
        name=name,
        description=description,
        parameters={
            "type": "object",
            "properties": {"_": {"type": "string", "description": "Unused. Pass empty string."}},
        },
    )
    new_tool = Tool(spec=tool_spec, handler=_bash_handler)
    registry.register(new_tool)

    logger.info("Registered bash tool '%s' (subprocess-isolated)", name)
    return f"Success: Bash tool '{name}' has been created and registered (subprocess-isolated)."
